node -e "
const N = 100_000;
const RUNS = 15;

function makeRandom() {
  const a = new Array(N);
  for (let i = 0; i < N; i++) a[i] = Math.random();
  return a;
}

function makeSorted() {
  const a = new Array(N);
  for (let i = 0; i < N; i++) a[i] = i;
  return a;
}

function timeSort(copyFn) {
  const arr = copyFn();
  const t0 = performance.now();
  arr.sort((x, y) => x - y);
  return performance.now() - t0;
}

function median(sorted) {
  const m = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[m] : (sorted[m - 1] + sorted[m]) / 2;
}

function bootstrapMedianCI(values, B = 10000, alpha = 0.05) {
  const n = values.length;
  const meds = new Array(B);
  for (let b = 0; b < B; b++) {
    const sample = new Array(n);
    for (let i = 0; i < n; i++) sample[i] = values[Math.floor(Math.random() * n)];
    sample.sort((a, b) => a - b);
    meds[b] = median(sample);
  }
  meds.sort((a, b) => a - b);
  const lo = meds[Math.floor((alpha / 2) * B)];
  const hi = meds[Math.floor((1 - alpha / 2) * B) - 1];
  return { lo, hi };
}

// warmup
for (let i = 0; i < 3; i++) { timeSort(makeRandom); timeSort(makeSorted); }

const randomTimes = [];
const sortedTimes = [];
for (let r = 0; r < RUNS; r++) {
  randomTimes.push(timeSort(makeRandom));
  sortedTimes.push(timeSort(makeSorted));
}

randomTimes.sort((a, b) => a - b);
sortedTimes.sort((a, b) => a - b);

const rMed = median(randomTimes);
const sMed = median(sortedTimes);
const rCI = bootstrapMedianCI(randomTimes);
const sCI = bootstrapMedianCI(sortedTimes);

console.log(JSON.stringify({
  node: process.version,
  N,
  runs: RUNS,
  random_ms: { median: rMed, ci95: [rCI.lo, rCI.hi], samples: randomTimes },
  sorted_ms: { median: sMed, ci95: [sCI.lo, sCI.hi], samples: sortedTimes },
}, null, 2));
"

node --expose-gc -e "
const N = 100_000;
const RUNS = 30;

function makeRandom() {
  const a = new Array(N);
  for (let i = 0; i < N; i++) a[i] = Math.random();
  return a;
}

function makeSorted() {
  const a = new Array(N);
  for (let i = 0; i < N; i++) a[i] = i;
  return a;
}

function timeSort(arr) {
  const copy = arr.slice();
  if (global.gc) global.gc();
  const t0 = performance.now();
  copy.sort((x, y) => x - y);
  return performance.now() - t0;
}

function median(sorted) {
  const m = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[m] : (sorted[m - 1] + sorted[m]) / 2;
}

function bootstrapMedianCI(values, B = 10000, alpha = 0.05) {
  const n = values.length;
  const meds = new Array(B);
  for (let b = 0; b < B; b++) {
    const sample = new Array(n);
    for (let i = 0; i < n; i++) sample[i] = values[Math.floor(Math.random() * n)];
    sample.sort((a, b) => a - b);
    meds[b] = median(sample);
  }
  meds.sort((a, b) => a - b);
  const lo = meds[Math.floor((alpha / 2) * B)];
  const hi = meds[Math.floor((1 - alpha / 2) * B) - 1];
  return { lo, hi };
}

const randomBase = makeRandom();
const sortedBase = makeSorted();

for (let i = 0; i < 5; i++) timeSort(randomBase);

const randomTimes = [];
const sortedTimes = [];
for (let r = 0; r < RUNS; r++) {
  randomTimes.push(timeSort(randomBase.map((_, i) => Math.random())));
  sortedTimes.push(timeSort(sortedBase));
}

const rMed = median([...randomTimes].sort((a,b)=>a-b));
const sMed = median([...sortedTimes].sort((a,b)=>a-b));
const rCI = bootstrapMedianCI(randomTimes);
const sCI = bootstrapMedianCI(sortedTimes);

console.log('Node', process.version, '| N=', N, '| runs=', RUNS, '| gc between runs');
console.log('Random:  median', rMed.toFixed(3), 'ms | 95% bootstrap CI [', rCI.lo.toFixed(3), ',', rCI.hi.toFixed(3), ']');
console.log('Sorted:  median', sMed.toFixed(3), 'ms | 95% bootstrap CI [', sCI.lo.toFixed(3), ',', sCI.hi.toFixed(3), ']');
console.log('Ratio (random/sorted):', (rMed/sMed).toFixed(2) + 'x');
"

